/* KiroClops measurement explorer.
 *
 * Plain JavaScript, no dependencies, no network requests except this page's own relative files
 * (data.js and frames/). data.js is generated by build_data.py from three real recordings that
 * were measured with kiroclops.cloud.execution.measure_direct, the code path of the AWS worker;
 * this file only draws what that measurement returned:
 *
 *   - a frame viewer with the measured box, anchor and trail of every object (and the measured
 *     connector endpoints of the SVG recording); a frame with no valid measurement gets no
 *     position at all, only a note saying why;
 *   - the raw x and y tracks over time with the events as labelled markers, each drawn as the
 *     interval between the two real frames that bracket it;
 *   - the events table, and for the game recording the receipt of the same recording on the
 *     live AWS COOL worker.
 */
(function () {
  'use strict';

  const D = window.EXPLORER_DATA;
  const host = document.getElementById('explorer');
  if (!host) return;
  if (!D || !Array.isArray(D.recordings) || !D.recordings.length) { host.textContent = 'data.js is missing.'; return; }

  /* ------------------------------------------------------------------ helpers */
  const NS = 'http://www.w3.org/2000/svg';
  const TIMES = '×', MID = '·', ENDASH = '–', NB = ' ';
  const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
  const secs = (v) => v.toFixed(3) + NB + 's';
  const FONT = getComputedStyle(document.body).fontFamily;

  function el(tag, props, ...kids) {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(props || {})) {
      if (v === undefined || v === null || v === false) continue;
      if (k === 'class') node.className = v;
      else if (k === 'text') node.textContent = v;
      else if (k.startsWith('on')) node.addEventListener(k.slice(2), v);
      else node.setAttribute(k, v === true ? '' : v);
    }
    append(node, kids);
    return node;
  }
  function append(node, kids) {
    for (const kid of kids.flat(Infinity)) {
      if (kid === undefined || kid === null || kid === false) continue;
      node.append(typeof kid === 'object' ? kid : document.createTextNode(String(kid)));
    }
    return node;
  }
  function sv(tag, props, ...kids) {
    const node = document.createElementNS(NS, tag);
    for (const [k, v] of Object.entries(props || {})) if (v !== undefined && v !== null && v !== false) node.setAttribute(k, v);
    append(node, kids);
    return node;
  }
  const setText = (node, text) => { if (node && node.textContent !== text) node.textContent = text; };
  const mctx = document.createElement('canvas').getContext('2d');
  function measure(text, size, weight) { mctx.font = (weight || 400) + ' ' + size + 'px ' + FONT; return mctx.measureText(text).width; }

  /* Event types: colour and marker shape. Unknown types still get a neutral marker. */
  const EVENT_STYLE = {
    motion_start: { color: '#34d399', shape: 'tri', short: 'start' },
    reversal: { color: '#fbbf24', shape: 'dia', short: 'reversal' },
    stop: { color: '#4dd0e1', shape: 'sq', short: 'stop' },
    settled: { color: '#a78bfa', shape: 'sqo', short: 'settled' },
    overshoot: { color: '#fb7185', shape: 'circ', short: 'overshoot' },
    oscillation: { color: '#f9a8d4', shape: 'circo', short: 'oscillation' },
    connection_attached: { color: '#67e8f9', shape: 'plus', short: 'attached' },
    connection_detached: { color: '#fb7185', shape: 'cross', short: 'detached' },
    overlap_enter: { color: '#fdba74', shape: 'tri', short: 'overlap in' },
    overlap_leave: { color: '#fdba74', shape: 'trio', short: 'overlap out' },
  };
  const styleOf = (ty) => EVENT_STYLE[ty] || { color: '#94a3b8', shape: 'circ', short: ty.replace(/_/g, ' ') };
  const INPUT_COLOR = '#c3cae0';
  const SERIES_SHAPES = ['circ', 'sq', 'dia', 'tri'];
  /* A marker for series k: filled with the object's colour and a dark rim, drawn on its line. */
  function seriesMark(k, color, r) {
    const g = glyph(SERIES_SHAPES[k % SERIES_SHAPES.length], color, r);
    g.setAttribute('fill', color); g.setAttribute('stroke', '#0a0f1e'); g.setAttribute('stroke-width', 1.3);
    return g;
  }
  const RECENT_S = 0.25;   /* an event counts as "just happened" for this long after its bracket */
  const TRAIL_S = 0.6;     /* length of the drawn trail in recorded time */

  /* A glyph centred on (0,0). Filled shapes are the event itself; hollow ones are its sibling event. */
  function glyph(shape, color, r) {
    const fill = !shape.endsWith('o') && shape !== 'plus' && shape !== 'cross';
    const base = shape.replace(/o$/, '');
    const common = { fill: fill ? color : 'none', stroke: color, 'stroke-width': fill ? 1 : 2, 'stroke-linejoin': 'round', 'stroke-linecap': 'round' };
    const R = r || 5.5;
    switch (base) {
      case 'tri': return sv('path', { ...common, d: 'M' + (-R * 0.75) + ' ' + (-R) + 'L' + R + ' 0L' + (-R * 0.75) + ' ' + R + 'Z' });
      case 'dia': return sv('path', { ...common, d: 'M0 ' + (-R * 1.1) + 'L' + (R * 1.1) + ' 0L0 ' + (R * 1.1) + 'L' + (-R * 1.1) + ' 0Z' });
      case 'sq': return sv('rect', { ...common, x: -R * 0.85, y: -R * 0.85, width: R * 1.7, height: R * 1.7, rx: 1 });
      case 'circ': return sv('circle', { ...common, r: R * 0.9 });
      case 'plus': return sv('path', { ...common, d: 'M' + (-R) + ' 0H' + R + 'M0 ' + (-R) + 'V' + R });
      case 'cross': return sv('path', { ...common, d: 'M' + (-R * 0.8) + ' ' + (-R * 0.8) + 'L' + (R * 0.8) + ' ' + (R * 0.8) + 'M' + (R * 0.8) + ' ' + (-R * 0.8) + 'L' + (-R * 0.8) + ' ' + (R * 0.8) });
      default: return sv('circle', { ...common, r: R * 0.9 });
    }
  }
  function glyphIcon(ty) {
    const st = styleOf(ty);
    return sv('svg', { class: 'gly', viewBox: '-8 -8 16 16', width: 14, height: 14, 'aria-hidden': 'true', focusable: 'false' }, glyph(st.shape, st.color, 5));
  }

  const REASON_TEXT = {
    outside_expected_lifecycle: 'outside its expected lifecycle (not in the scene yet)',
    tracking_failure: 'template match below the score or margin limit',
    before_selection_frame: 'before the frame it was selected in',
    camera_motion: 'the camera moved',
    camera_unverified: 'the camera could not be verified',
    visible_boundary_not_found: 'its visible outline was not found',
    ambiguous_visible_boundary: 'its visible outline was ambiguous',
    node_unobservable: 'an end object has no valid measurement',
    visible_connection_not_found: 'no visible connector found',
    ambiguous_visible_connection: 'the connector was ambiguous',
    ambiguous_node_geometry: 'an end box was ambiguous',
    endpoint_clipped_by_search_region: 'an endpoint was clipped by the search region',
    unsupported_connection_geometry: 'unsupported connector geometry',
  };
  const reasonText = (r) => REASON_TEXT[r] || String(r).replace(/_/g, ' ');

  /* ------------------------------------------------------------------ data preparation */
  const recs = D.recordings;
  recs.forEach(function (rec, idx) {
    rec.idx = idx;
    rec.byId = {};
    rec.objects.forEach((o, k) => { o.k = k; rec.byId[o.id] = o; });
    rec.t0 = rec.t[0];
    rec.t1 = rec.t[rec.n - 1];
    rec.rt = { imgs: new Array(rec.unique_images).fill(null), queue: null, active: 0, loaded: 0, failed: 0, tries: {}, wait: {} };
    const ends = rec.events.map((e) => e.f[1]).sort((a, b) => a - b);
    const turn = rec.events.find((e) => e.ty === 'reversal');
    rec.startFrame = turn ? turn.f[1] : ends.length ? ends[Math.floor(ends.length / 2)] : Math.floor(rec.n / 3);
    if (rec.events.length) {
      const lo = Math.min(...rec.events.map((e) => e.t[0])), hi = Math.max(...rec.events.map((e) => e.t[1]));
      rec.focus = [Math.max(rec.t0, lo - 0.12), Math.min(rec.t1, hi + 0.3)];
    } else rec.focus = [rec.t0, rec.t1];
  });
  const rowOk = (row) => Array.isArray(row);

  /* Largest frame index whose time is <= t, and the nearest frame to t. */
  function frameAt(rec, t) {
    const a = rec.t;
    let lo = 0, hi = a.length - 1;
    if (t <= a[0]) return 0;
    while (lo < hi) { const mid = (lo + hi + 1) >> 1; if (a[mid] <= t) lo = mid; else hi = mid - 1; }
    return lo;
  }
  function nearestFrame(rec, t) {
    const i = frameAt(rec, t);
    return i + 1 < rec.n && Math.abs(rec.t[i + 1] - t) < Math.abs(t - rec.t[i]) ? i + 1 : i;
  }
  /* Events that happened in the last RECENT_S seconds before frame i (their bracket is complete). */
  function currentEvents(rec, i) {
    const out = [], T = rec.t[i];
    rec.events.forEach((e, n) => { if (e.f[1] <= i && T - e.t[1] <= RECENT_S) out.push(n); });
    return out;
  }

  /* ------------------------------------------------------------------ frame images */
  const RETRIES = 3;      /* a frame that fails to load is asked for again twice before it is given up */
  const imgUrl = (rec, k) => rec.dir + String(k).padStart(rec.pad, '0') + '.' + rec.ext;
  function ensureQueue(rec) {
    const rt = rec.rt;
    if (rt.queue) return;
    const seen = new Set(), q = [];
    const order = [rec.src[rec.startFrame]];
    for (let i = 0; i < rec.n; i++) order.push(rec.src[i]);
    for (const k of order) if (!seen.has(k)) { seen.add(k); q.push(k); }
    rt.queue = q;
  }
  function pump(rec) {
    const rt = rec.rt;
    ensureQueue(rec);
    while (rt.active < 6 && rt.queue.length) request(rec, rt.queue.shift());
  }
  function request(rec, k) {
    const rt = rec.rt;
    if (rt.imgs[k] || rt.wait[k]) return rt.imgs[k];
    const img = new Image();
    img.decoding = 'async';
    img.onload = () => { rt.active--; rt.loaded++; pump(rec); imageArrived(rec, k); };
    img.onerror = () => {
      rt.active--;
      rt.tries[k] = (rt.tries[k] || 0) + 1;
      if (rt.tries[k] < RETRIES) {      /* a transient network error: ask again shortly */
        rt.imgs[k] = null; rt.wait[k] = true;
        setTimeout(() => { rt.wait[k] = false; request(rec, k); pump(rec); }, 400 * rt.tries[k]);
      } else { rt.failed++; imageArrived(rec, k); }
      pump(rec);
    };
    img.src = imgUrl(rec, k);
    rt.imgs[k] = img;
    rt.active++;
    return img;
  }
  function wantImage(rec, k) {      /* load this image next, ahead of the background queue */
    const rt = rec.rt;
    if (rt.imgs[k]) return;
    ensureQueue(rec);
    const at = rt.queue.indexOf(k);
    if (at > 0) rt.queue.splice(at, 1);
    request(rec, k);
  }
  const imgReady = (img) => !!img && img.complete && img.naturalWidth > 0;
  const frameReady = (rec, i) => imgReady(rec.rt.imgs[rec.src[i]]);
  const frameGivenUp = (rec, i) => (rec.rt.tries[rec.src[i]] || 0) >= RETRIES;
  function imageArrived(rec, k) {
    if (S.rec !== rec || !ui) return;
    updateLoading();
    if (rec.src[S.i] === k) paintFrame();
  }

  /* ------------------------------------------------------------------ state */
  const S = { rec: null, i: 0, playing: false, pristine: true, speed: 1, view: 'all', hover: -1, show: { boxes: true, trails: true, conn: true, cam: false } };
  let ui = null;           /* DOM references of the open recording */
  let playClip = 0, playLast = 0, playRaf = 0;
  const tip = el('div', { class: 'tip', role: 'tooltip', hidden: true });
  document.body.append(tip);

  /* ------------------------------------------------------------------ page */
  const tabsRow = el('div', { class: 'tabs', role: 'tablist', 'aria-label': 'Recordings' });
  const panel = el('div', { class: 'panel', role: 'tabpanel', tabindex: '-1' });
  const live = el('div', { class: 'sr-only', 'aria-live': 'polite', 'aria-atomic': 'true' });
  host.append(tabsRow, panel, live);

  const tabButtons = recs.map((rec, k) => {
    const btn = el('button', { class: 'tab', type: 'button', role: 'tab', id: 'tab-' + rec.id, 'aria-controls': 'panel', 'aria-selected': 'false', tabindex: '-1',
      onclick: () => selectTab(k) },
      el('span', { class: 'tab-top' }, el('span', { class: 'n', text: String(k + 1) }), el('span', { class: 'tt', text: rec.tab })),
      el('span', { class: 'ts', text: rec.tab_sub }));
    btn.addEventListener('keydown', (ev) => {
      let to = -1;
      if (ev.key === 'ArrowRight') to = (k + 1) % recs.length;
      else if (ev.key === 'ArrowLeft') to = (k + recs.length - 1) % recs.length;
      else if (ev.key === 'Home') to = 0;
      else if (ev.key === 'End') to = recs.length - 1;
      if (to >= 0) { ev.preventDefault(); selectTab(to, true); }
    });
    tabsRow.append(btn);
    return btn;
  });
  panel.setAttribute('id', 'panel');

  function selectTab(k, focus) {
    const rec = recs[k];
    pause();
    hideTip();
    if (ui && ui.teardown) ui.teardown();
    S.rec = rec; S.hover = -1; S.view = 'all'; S.pristine = true;
    tabButtons.forEach((b, n) => { b.setAttribute('aria-selected', n === k ? 'true' : 'false'); b.tabIndex = n === k ? 0 : -1; });
    if (focus) tabButtons[k].focus();
    panel.setAttribute('aria-labelledby', 'tab-' + rec.id);
    ui = { teardown: null };
    panel.replaceChildren(...[buildViewer(rec), buildCharts(rec), buildEvents(rec), buildReceipt(rec), buildGuide(rec)].filter(Boolean));
    if (ui.chartHost.clientWidth < 560) setView('motion', true);
    S.i = rec.startFrame;
    pump(rec);
    wantImage(rec, rec.src[S.i]);
    layoutAll();
    paint();
    try { history.replaceState(null, '', '#' + rec.id); } catch (e) { /* file:// in some browsers */ }
  }

  /* ------------------------------------------------------------------ viewer */
  function buildViewer(rec) {
    const chips = [];
    chips.push(rec.n + ' frames', rec.size[0] + NB + TIMES + NB + rec.size[1] + ' px', rec.clock.duration_s.toFixed(2) + ' s');
    chips.push(rec.id === 'game' ? '60 Hz' : 'browser clock, median ' + rec.clock.median_ms.toFixed(1) + ' ms');
    chips.push('static camera ' + rec.camera.n_pass + '/' + rec.camera.n);
    const worst = Math.min(...rec.objects.map((o) => o.valid_ratio));
    chips.push('valid frames ' + (worst * 100).toFixed(0) + '%');

    const canvas = el('canvas', { role: 'img', 'aria-label': 'Frame of the recording with the measured objects drawn on it' });
    const note = el('div', { class: 'inv-note', hidden: true });
    const loadBar = el('i');
    const loading = el('div', { class: 'loading', hidden: true }, el('span', { class: 'load-t' }), el('span', { class: 'load-b' }, loadBar));
    const screen = el('div', { class: 'screen' }, canvas, note, loading);

    const playBtn = el('button', { class: 'btn primary play', type: 'button', onclick: () => (S.playing ? pause() : play()), text: 'Play' });
    const prev = el('button', { class: 'btn step', type: 'button', 'aria-label': 'Previous frame', onclick: () => { pause(); setFrame(S.i - 1, true); }, text: '‹' });
    const next = el('button', { class: 'btn step', type: 'button', 'aria-label': 'Next frame', onclick: () => { pause(); setFrame(S.i + 1, true); }, text: '›' });
    const scrub = el('input', { type: 'range', min: 0, max: rec.n - 1, step: 1, value: 0, 'aria-label': 'Frame', title: 'Arrow keys step one frame, Home and End jump to the ends, Space plays or pauses' });
    scrub.addEventListener('input', () => { pause(); setFrame(+scrub.value, true); });
    scrub.addEventListener('keydown', (ev) => { if (ev.key === ' ') { ev.preventDefault(); S.playing ? pause() : play(); } });
    const ticks = el('div', { class: 'ticks', 'aria-hidden': 'true' });
    const seen = new Set();
    rec.events.forEach((e) => {
      const f = e.f[1];
      if (seen.has(f)) return;
      seen.add(f);
      ticks.append(el('i', { style: '--p:' + (f / Math.max(1, rec.n - 1)) }));
    });
    const clock = el('span', { class: 'clock num' });
    const transport = el('div', { class: 'transport' }, playBtn, prev, next, el('div', { class: 'scrub' }, ticks, scrub), clock);

    const toggles = [];
    function toggle(key, label, title) {
      const b = el('button', { class: 'tog', type: 'button', 'aria-pressed': String(S.show[key]), title, text: label,
        onclick: () => { S.show[key] = !S.show[key]; b.setAttribute('aria-pressed', String(S.show[key])); paintFrame(); } });
      toggles.push(b);
      return b;
    }
    toggle('boxes', 'Boxes', 'Measured box, anchor ring and label of each object');
    toggle('trails', 'Trails', 'The anchor over the last ' + TRAIL_S + ' s of recorded time');
    if (rec.connections.length) toggle('conn', 'Connectors', 'Measured end points of the visible connectors');
    toggle('cam', 'Camera patch', 'Background patch used to check that the camera stayed still');
    const speed = el('select', { class: 'speed', 'aria-label': 'Playback speed', onchange: () => { S.speed = +speed.value; } },
      [[0.1, '0.1' + TIMES], [0.25, '0.25' + TIMES], [0.5, '0.5' + TIMES], [1, '1' + TIMES + ' (recorded time)']].map(([v, t]) => el('option', { value: v, text: t, selected: v === S.speed })));
    const opts = el('div', { class: 'opts' },
      el('div', { class: 'tg', role: 'group', 'aria-label': 'Overlays' }, toggles),
      el('label', { class: 'spd' }, el('span', { text: 'Speed' }), speed));

    const legend = el('p', { class: 'legend-line' },
      el('span', { class: 'lg' }, el('i', { class: 'lg-box' }), 'measured box'), ' ',
      el('span', { class: 'lg' }, el('i', { class: 'lg-ring' }), 'anchor (x, y)'), ' ',
      el('span', { class: 'lg' }, el('i', { class: 'lg-trail' }), 'trail'), ' ',
      rec.connections.length ? el('span', { class: 'lg' }, el('i', { class: 'lg-conn' }), 'connector ends') : null,
      ' No position is drawn for a frame without a valid measurement.');

    /* readout: the measured values of the current frame, as compact tables */
    const objRows = rec.objects.map((o) => {
      const cells = ['x', 'y', 'box', 'score', 'margin'].map((c) => el('td', { class: 'c-' + c }));
      const tr = el('tr', { class: 'ob', style: '--c:' + o.color },
        el('th', { scope: 'row' }, el('span', { class: 'on' }, el('i', { class: 'sw' }), el('b', { text: o.id })), el('span', { class: 'ol', text: o.label })), cells);
      return { o, tr, cells };
    });
    const connRows = rec.connections.map((c) => {
      const cells = [el('td', { class: 'c-s' }), el('td', { class: 'c-e' })];
      return { c, cells, tr: el('tr', { class: 'ob' }, el('th', { scope: 'row' }, el('span', { class: 'on' }, el('i', { class: 'sw conn-sw' }), el('b', { text: c.from + '\u2013' + c.to }))), cells) };
    });
    const table = (cls, heads, rows, label) => el('table', { class: 'rotbl ' + cls },
      el('caption', { class: 'sr-only', text: label }),
      el('thead', {}, el('tr', {}, heads.map(([h, tip]) => el('th', { scope: 'col', title: tip, text: h })))),
      el('tbody', {}, rows));
    const objTable = table('objt', [['object', 'Tracked object'], ['x', 'Measured anchor x, in image pixels (pixel index, so the pixel centre is +0.5)'], ['y', 'Measured anchor y, in image pixels (pixel index, so the pixel centre is +0.5)'],
      ['box', 'Width and height of the measured box, in pixels'], ['score', 'Template match score: the peak of the normalised cross-correlation (TM_CCOEFF_NORMED)'],
      ['margin', 'Match score minus the next-best peak; 2.00 means no competing peak in the search window']], objRows.map((r) => r.tr), 'Measured values of each object at this frame');
    const connTable = connRows.length ? table('connt', [['connector', 'Visible connector between two objects'], ['start (x, y)', 'Measured start of the visible connector, in image pixels'], ['end (x, y)', 'Measured end of the visible connector, in image pixels']], connRows.map((r) => r.tr), 'Measured end points of each connector at this frame') : null;
    const tpls = el('ul', { class: 'tpls' }, rec.objects.map((o) => el('li', { style: '--c:' + o.color },
      el('img', { class: 'tpl' + (rec.smooth ? '' : ' px'), src: o.tpl, alt: 'Template of ' + o.id + ', ' + o.roi[2] + ' by ' + o.roi[3] + ' pixels' }),
      el('span', { class: 'tl' }, el('b', { text: o.id }), ' ' + o.roi[2] + TIMES + o.roi[3]))));
    const loupe = rec.size[0] <= 400 ? el('canvas', { class: 'loupe', role: 'img', 'aria-label': 'Magnified view of the tracked object with the measured box and anchor' }) : null;
    const loupeCap = el('figcaption', { class: 'lc' });
    const camLine = el('p', { class: 'cam' });
    const nowList = el('ul', { class: 'now-list' });
    const readout = el('aside', { class: 'readout', 'aria-labelledby': 'ro-h' },
      el('h3', { id: 'ro-h', text: 'Measured at this frame' }),
      el('p', { class: 'ro-time num' }),
      objTable, connTable,
      loupe ? el('figure', { class: 'loupe-f' }, loupe, loupeCap) : null,
      el('h4', { text: 'What the tracker looks for' }), tpls,
      camLine,
      el('h4', { text: 'Events in the last ' + RECENT_S + ' s' }),
      nowList);

    const v = el('section', { class: 'card viewer', 'aria-labelledby': 'v-title' },
      el('div', { class: 'v-head' }, el('h2', { id: 'v-title', text: rec.title }),
        el('p', { class: 'v-chips' }, chips.map((c) => el('span', { class: 'badge', text: c })))),
      el('p', { class: 'v-blurb', text: rec.blurb }),
      el('div', { class: 'v-grid' }, el('div', { class: 'v-main' }, screen, transport, opts, legend), readout));

    Object.assign(ui, { canvas, ctx: canvas.getContext('2d'), screen, note, loading, loadBar, playBtn, scrub, clock, objRows, connRows, camLine, nowList, loupe, loupeCap,
      roTime: readout.querySelector('.ro-time'), view: null, lastKey: '' });

    const ro = new ResizeObserver(() => { if (sizeCanvas()) paintFrame(); });
    ro.observe(screen);
    const prevTeardown = ui.teardown;
    ui.teardown = () => { ro.disconnect(); if (prevTeardown) prevTeardown(); };
    return v;
  }

  function sizeCanvas() {
    const rec = S.rec;
    const avail = ui.screen.clientWidth;
    if (avail < 50) return false;
    const w = rec.size[0], h = rec.size[1];
    let cssW;
    if (!rec.smooth) { const k = avail / w; cssW = k >= 2 ? Math.floor(k) * w : avail; }    /* pixel art: whole-number zoom when it fits */
    else cssW = Math.min(avail, w);
    cssW = Math.max(100, Math.round(cssW));
    const cssH = Math.round(cssW * h / w);
    const dpr = Math.min(window.devicePixelRatio || 1, 3);
    const bw = Math.round(cssW * dpr), bh = Math.round(cssH * dpr);
    const same = ui.view && ui.view.cssW === cssW && ui.view.dpr === dpr;
    if (same) return false;
    ui.canvas.style.width = cssW + 'px';
    ui.canvas.style.height = cssH + 'px';
    ui.canvas.width = bw; ui.canvas.height = bh;
    ui.view = { cssW, cssH, dpr, k: bw / w };
    return true;
  }

  function updateLoading() {
    const rec = S.rec, rt = rec.rt;
    const done = rt.loaded + rt.failed, total = rec.unique_images;
    const show = done < total && !frameReady(rec, S.i);
    ui.loading.hidden = !show;
    if (show) {
      setText(ui.loading.querySelector('.load-t'), 'Loading frames ' + done + ' / ' + total);
      ui.loadBar.style.width = (100 * done / total).toFixed(0) + '%';
    }
  }

  /* ------------------------------------------------------------------ drawing the frame */
  function paintFrame() {
    if (!ui || !ui.view) return;
    const rec = S.rec, { ctx, view } = ui, i = S.i;
    const W = ui.canvas.width, H = ui.canvas.height;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, W, H);
    ctx.imageSmoothingEnabled = rec.smooth;
    if (rec.smooth) ctx.imageSmoothingQuality = 'high';
    const k = rec.src[i], img = rec.rt.imgs[k];
    if (!imgReady(img)) {
      wantImage(rec, k);
      ctx.fillStyle = '#050810'; ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#9aa6c8'; ctx.font = (13 * view.dpr) + 'px ' + FONT; ctx.textAlign = 'center';
      ctx.fillText(img && img.complete ? 'This frame could not be loaded' : 'Loading frame ' + i + '\u2026', W / 2, H / 2);
      ctx.textAlign = 'start';
      drawLoupe(null);
      updateLoading();
      return;
    }
    ctx.drawImage(img, 0, 0, W, H);
    updateLoading();
    overlay(ctx, rec, i, view);
    drawLoupe(img);
  }

  /* Measured x and y are pixel indexes, so the pixel's centre is half a pixel further: draw anchors and
     connector end points at +0.5. Boxes are edges between pixels and need no offset. */
  const HALF = 0.5;
  function overlay(ctx, rec, i, view) {
    const s = view.k, d = view.dpr;
    /* camera patch */
    if (S.show.cam) {
      ctx.save();
      ctx.setLineDash([6 * d, 4 * d]); ctx.lineWidth = 1.5 * d; ctx.strokeStyle = 'rgba(203,213,245,.85)';
      for (const r of rec.camera.rois) ctx.strokeRect(r[0] * s, r[1] * s, r[2] * s, r[3] * s);
      ctx.setLineDash([]);
      ctx.font = '600 ' + (11 * d) + 'px ' + FONT;
      for (const r of rec.camera.rois) pill(ctx, 'camera check patch', r[0] * s, (r[1] + r[3]) * s + 3 * d, d, '#cbd5f5', true);
      ctx.restore();
    }
    /* trails: only while the object has a valid measurement now, and never across an invalid frame */
    if (S.show.trails) {
      for (const o of rec.objects) {
        if (!rowOk(o.f[i])) continue;
        const T = rec.t[i];
        let j = i;
        while (j > 0 && T - rec.t[j - 1] <= TRAIL_S && rowOk(o.f[j - 1])) j--;
        ctx.save();
        ctx.lineCap = 'round'; ctx.lineJoin = 'round';
        for (let m = Math.max(j, 1); m <= i; m++) {
          const a = o.f[m - 1], b = o.f[m];
          if (!rowOk(a) || !rowOk(b)) continue;
          const age = (T - rec.t[m]) / TRAIL_S;
          ctx.globalAlpha = clamp(0.9 * (1 - age), 0.08, 0.9);
          ctx.strokeStyle = o.color; ctx.lineWidth = 2.2 * d;
          ctx.beginPath(); ctx.moveTo((a[0] + HALF) * s, (a[1] + HALF) * s); ctx.lineTo((b[0] + HALF) * s, (b[1] + HALF) * s); ctx.stroke();
        }
        ctx.restore();
      }
    }
    /* connectors: the measured end points; nothing for a frame without a measurement */
    if (S.show.conn) {
      for (const c of rec.connections) {
        const r = c.f[i];
        if (!rowOk(r)) continue;
        const ax = (r[0] + HALF) * s, ay = (r[1] + HALF) * s, bx = (r[2] + HALF) * s, by = (r[3] + HALF) * s;
        ctx.save();
        ctx.lineCap = 'round';
        ctx.strokeStyle = 'rgba(52,211,153,.9)'; ctx.lineWidth = 2.4 * d;
        ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by); ctx.stroke();
        for (const [x, y, occluded] of [[ax, ay, r[5]], [bx, by, r[6]]]) {
          ctx.beginPath(); ctx.arc(x, y, 5 * d, 0, 6.2832);
          ctx.fillStyle = 'rgba(5,8,16,.85)'; ctx.fill();
          ctx.lineWidth = 2 * d; ctx.strokeStyle = occluded ? '#fbbf24' : '#34d399'; ctx.stroke();
        }
        ctx.font = '600 ' + (11 * d) + 'px ' + FONT;
        pill(ctx, c.from + '\u2013' + c.to, (ax + bx) / 2 + 6 * d, (ay + by) / 2 - 8 * d, d, '#34d399', false);
        ctx.restore();
      }
    }
    /* boxes, anchors, labels: valid frames only */
    if (S.show.boxes) {
      ctx.save();
      ctx.font = '600 ' + (11.5 * d) + 'px ' + FONT;
      for (const o of rec.objects) {
        const r = o.f[i];
        if (!rowOk(r)) continue;
        const x = (r[0] + HALF) * s, y = (r[1] + HALF) * s, left = r[2] * s, top = r[3] * s, w = r[4] * s, h = r[5] * s;
        ctx.lineWidth = 3.6 * d; ctx.strokeStyle = 'rgba(5,8,16,.75)'; ctx.strokeRect(left, top, w, h);
        ctx.lineWidth = 1.8 * d; ctx.strokeStyle = o.color; ctx.strokeRect(left, top, w, h);
        ctx.globalAlpha = 0.12; ctx.fillStyle = o.color; ctx.fillRect(left, top, w, h); ctx.globalAlpha = 1;
        ctx.beginPath(); ctx.arc(x, y, 5.5 * d, 0, 6.2832);
        ctx.lineWidth = 3.6 * d; ctx.strokeStyle = 'rgba(5,8,16,.8)'; ctx.stroke();
        ctx.lineWidth = 1.8 * d; ctx.strokeStyle = '#ffffff'; ctx.stroke();
        ctx.beginPath(); ctx.arc(x, y, 1.6 * d, 0, 6.2832); ctx.fillStyle = o.color; ctx.fill();
      }
      for (const o of rec.objects) {
        const r = o.f[i];
        if (!rowOk(r)) continue;
        pill(ctx, o.id, r[2] * s, r[3] * s - 6 * d, d, o.color, false);
      }
      ctx.restore();
    }
  }

  /* Loupe for small recordings: the pixels around the tracked object, one square per recorded pixel. */
  const LOUPE = [40, 24];
  function drawLoupe(img) {
    const c = ui.loupe;
    if (!c) return;
    const rec = S.rec, o = rec.objects[0], row = o.f[S.i];
    const dpr = Math.min(window.devicePixelRatio || 1, 3);
    if (c.clientWidth < 40) return;
    const cw = Math.round(c.clientWidth * dpr), ch = Math.round(cw * LOUPE[1] / LOUPE[0]);
    if (c.width !== cw || c.height !== ch) { c.width = cw; c.height = ch; }
    const g = c.getContext('2d');
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.imageSmoothingEnabled = false;
    g.fillStyle = '#050810'; g.fillRect(0, 0, cw, ch);
    if (!img || !rowOk(row)) {
      g.fillStyle = '#9aa6c8'; g.font = (13 * dpr) + 'px ' + FONT; g.textAlign = 'center';
      g.fillText(img ? 'no measurement: nothing to magnify' : 'loading\u2026', cw / 2, ch / 2);
      setText(ui.loupeCap, 'Loupe on ' + o.id + ': ' + (img ? 'no measurement at this frame.' : 'loading.'));
      return;
    }
    const LW = LOUPE[0], LH = LOUPE[1];
    const sx = clamp(Math.round(row[0] + HALF - LW / 2), 0, rec.size[0] - LW), sy = clamp(Math.round(row[1] + HALF - LH / 2), 0, rec.size[1] - LH);
    g.drawImage(img, sx, sy, LW, LH, 0, 0, cw, ch);
    const k = cw / LW;
    g.lineWidth = 1; g.strokeStyle = 'rgba(255,255,255,.09)';
    g.beginPath();
    for (let x = 1; x < LW; x++) { g.moveTo(x * k, 0); g.lineTo(x * k, ch); }
    for (let y = 1; y < LH; y++) { g.moveTo(0, y * k); g.lineTo(cw, y * k); }
    g.stroke();
    g.lineWidth = 2.2 * dpr; g.strokeStyle = o.color;
    g.strokeRect((row[2] - sx) * k, (row[3] - sy) * k, row[4] * k, row[5] * k);
    g.beginPath(); g.arc((row[0] + HALF - sx) * k, (row[1] + HALF - sy) * k, 0.62 * k, 0, 6.2832);
    g.lineWidth = 4.4 * dpr; g.strokeStyle = 'rgba(5,8,16,.85)'; g.stroke();
    g.lineWidth = 2.2 * dpr; g.strokeStyle = '#ffffff'; g.stroke();
    setText(ui.loupeCap, 'Loupe on ' + o.id + ': ' + LW + TIMES + LH + ' pixels around the anchor, magnified ' + (k / dpr).toFixed(1) + TIMES + '; each square is one pixel of the recording.');
  }

  /* A small label with a dark backing, drawn above (x, y) = left/bottom corner; kept inside the canvas. */
  function pill(ctx, text, x, y, d, color, below) {
    const padX = 5 * d, h = 17 * d;
    const w = ctx.measureText(text).width + padX * 2;
    const W = ctx.canvas.width, H = ctx.canvas.height;
    let px = clamp(x, 2 * d, W - w - 2 * d), py = below ? y : y - h;
    if (py < 2 * d) py = below ? y : y + h + 12 * d;
    py = clamp(py, 2 * d, H - h - 2 * d);
    ctx.save();
    ctx.fillStyle = 'rgba(5,8,16,.82)';
    roundRect(ctx, px, py, w, h, 4 * d); ctx.fill();
    ctx.fillStyle = color; ctx.textBaseline = 'middle'; ctx.textAlign = 'start';
    ctx.fillText(text, px + padX, py + h / 2 + 0.5 * d);
    ctx.restore();
  }
  function roundRect(ctx, x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y); ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
  }

  /* ------------------------------------------------------------------ readout */
  function updateReadout() {
    const rec = S.rec, i = S.i;
    setText(ui.clock, secs(rec.t[i]) + ' ' + MID + ' ' + i + ' / ' + (rec.n - 1));
    const dt = i > 0 ? (rec.t[i] - rec.t[i - 1]) * 1000 : null;
    setText(ui.roTime, 'frame ' + i + ' of ' + rec.n + ' ' + MID + ' t = ' + secs(rec.t[i]) + (dt !== null ? ' ' + MID + ' ' + dt.toFixed(1) + NB + 'ms after the previous frame' : ''));
    const invalid = [];
    for (const r of ui.objRows) {
      const row = r.o.f[i], c = r.cells;
      if (rowOk(row)) {
        r.tr.classList.remove('bad');
        c[0].colSpan = 1;
        for (let n = 1; n < 5; n++) c[n].hidden = false;
        setText(c[0], row[0].toFixed(2));
        setText(c[1], row[1].toFixed(2));
        setText(c[2], (+row[4].toFixed(1)) + TIMES + (+row[5].toFixed(1)));
        setText(c[3], row[6] === null ? '\u2013' : row[6].toFixed(3));
        setText(c[4], row[7] === null ? '\u2013' : row[7].toFixed(2));
      } else {
        r.tr.classList.add('bad');
        c[0].colSpan = 5;
        for (let n = 1; n < 5; n++) c[n].hidden = true;
        let why = 'No measurement: ' + reasonText(row.r);
        if (row.p === 0) why += '; absent, confirmed by a whole-image search for its template';
        setText(c[0], why + '. No position is drawn.');
        invalid.push(r.o.id + ' (' + reasonText(row.r).replace(/ \(.*\)$/, '') + ')');
      }
    }
    for (const r of ui.connRows) {
      const row = r.c.f[i], c = r.cells;
      if (rowOk(row)) {
        r.tr.classList.remove('bad');
        c[0].colSpan = 1; c[1].hidden = false;
        setText(c[0], '(' + row[0].toFixed(1) + ', ' + row[1].toFixed(1) + ')');
        setText(c[1], '(' + row[2].toFixed(1) + ', ' + row[3].toFixed(1) + ')' + (row[5] || row[6] ? ' *' : ''));
        c[1].title = row[5] || row[6] ? 'An end is hidden by an overlapping ring and is flagged as occluded' : '';
      } else {
        r.tr.classList.add('bad');
        c[0].colSpan = 2; c[1].hidden = true;
        setText(c[0], 'No measurement: ' + reasonText(row.r) + '. Nothing is drawn.');
      }
    }
    const cam = rec.camera;
    setText(ui.camLine, 'Static camera check: ' + cam.n_pass + ' of ' + cam.n + ' frames pass (largest shift ' + cam.max_shift_px.toFixed(1) + ' px, limit ' + cam.limit_px.toFixed(1) + ' px).');
    if (invalid.length) { ui.note.hidden = false; setText(ui.note, 'No measurement: ' + invalid.join(', ')); }
    else ui.note.hidden = true;
    ui.canvas.setAttribute('aria-label', 'Frame ' + i + ' at ' + secs(rec.t[i]) + '. ' + rec.objects.map((o) => { const r = o.f[i]; return o.id + (rowOk(r) ? ' at x ' + r[0].toFixed(1) + ', y ' + r[1].toFixed(1) : ': no measurement'); }).join('; ') + '.');
  }

  /* ------------------------------------------------------------------ playback */
  function setFrame(i, announce) {
    const rec = S.rec;
    i = clamp(Math.round(i), 0, rec.n - 1);
    if (announce) S.pristine = false;
    if (i === S.i && ui.lastKey) return;
    S.i = i;
    paint();
    if (announce) announceFrame();
  }
  let announceTimer = 0;
  function announceFrame() {
    clearTimeout(announceTimer);
    announceTimer = setTimeout(() => {
      const rec = S.rec, i = S.i;
      live.textContent = 'Frame ' + i + ', ' + secs(rec.t[i]) + '. ' + rec.objects.map((o) => { const r = o.f[i]; return o.id + (rowOk(r) ? ' x ' + r[0].toFixed(1) + ', y ' + r[1].toFixed(1) : ' no measurement'); }).join('; ') + '.';
    }, 350);
  }
  /* Playback covers the time range chosen for the charts: the whole clip or the motion window. The first Play
     starts at the beginning of that range, so the first view (mid-motion) does not hide the start of the motion. */
  const rangeFrames = (rec) => { const r = viewRange(rec); return [nearestFrame(rec, r[0]), frameAt(rec, r[1])]; };
  function play() {
    const rec = S.rec;
    if (S.playing) return;
    const [f0, f1] = rangeFrames(rec);
    if (S.pristine || S.i >= f1) { S.i = f0; S.pristine = false; paint(); }
    S.playing = true;
    setText(ui.playBtn, 'Pause');
    playClip = rec.t[S.i]; playLast = performance.now();
    playRaf = requestAnimationFrame(tick);
  }
  function pause() {
    if (!S.playing) return;
    S.playing = false;
    cancelAnimationFrame(playRaf);
    if (ui && ui.playBtn) setText(ui.playBtn, S.i >= rangeFrames(S.rec)[1] ? 'Replay' : 'Play');
  }
  function tick(now) {
    if (!S.playing) return;
    const rec = S.rec;
    const end = rangeFrames(rec)[1];
    const dt = Math.min(now - playLast, 250);    /* a long stall (background tab) must not skip the clip */
    playLast = now;
    const target = playClip + dt / 1000 * S.speed;
    const j = Math.min(frameAt(rec, target), Math.max(end, S.i));
    if (j !== S.i && !frameReady(rec, j) && !frameGivenUp(rec, j)) {
      wantImage(rec, rec.src[j]);                /* buffering: hold the clock until the frame is here */
      updateLoading();
    } else {
      playClip = target;
      if (j !== S.i) { S.i = j; paint(); }
      for (let a = 1; a <= 4 && j + a < rec.n; a++) {   /* decode ahead so that drawing never stalls on decoding */
        const img = rec.rt.imgs[rec.src[j + a]];
        if (img && img.decode && !img.kcDecoded) { img.kcDecoded = true; img.decode().catch(() => {}); }
      }
      if (j >= end) { pause(); return; }
    }
    playRaf = requestAnimationFrame(tick);
  }

  /* ------------------------------------------------------------------ charts */
  function buildCharts(rec) {
    const legend = el('div', { class: 'ch-legend', role: 'group', 'aria-label': 'Objects' }, rec.objects.map((o) =>
      el('span', { class: 'ch-chip', style: '--c:' + o.color, title: 'Point at an object to highlight its lines',
        onmouseenter: () => highlight(o.id), onmouseleave: () => highlight(null) },
      sv('svg', { class: 'sw-line', width: 30, height: 12, viewBox: '0 0 30 12', 'aria-hidden': 'true', focusable: 'false' },
        sv('line', { x1: 1, x2: 29, y1: 6, y2: 6, stroke: o.color, 'stroke-width': 2.4, 'stroke-linecap': 'round' }),
        sv('g', { transform: 'translate(15 6)' }, seriesMark(o.k, o.color, 3.6))),
      el('b', { text: o.id }), ' ' + o.label)));
    const host = el('div', { class: 'ch-host' });
    const seg = el('div', { class: 'seg', role: 'group', 'aria-label': 'Time range' },
      el('button', { type: 'button', 'aria-pressed': 'true', text: 'Whole clip', onclick: () => setView('all') }),
      el('button', { type: 'button', 'aria-pressed': 'false', title: 'Zoom the time axis to the part of the clip where events happen', text: 'Motion window', onclick: () => setView('motion') }));
    const c = el('section', { class: 'card charts', 'aria-labelledby': 'ch-title' },
      el('div', { class: 'tl-head' }, el('h2', { id: 'ch-title', text: 'Tracks and events over time' }), seg),
      el('p', { class: 'cs', text: 'Raw x and y of every tracked object, one sample per frame, with a line break wherever a frame has no valid measurement. Each event is a marker on its object’s row; its bar spans the interval between the two real frames that bracket it. Click or drag to move through the clip.' }),
      legend, host,
      el('p', { class: 'ch-foot' }, 'Coloured ticks on the time axis mark the events. Lines that coincide are drawn on top of each other, widest first. y grows downward in the image, so the y axis is flipped: up on the chart is up in the frame.'));
    ui.chartHost = host; ui.seg = seg; ui.chart = null;
    const ro = new ResizeObserver(() => { if (ui && ui.chartHost && Math.abs((ui.chartW || 0) - host.clientWidth) > 0.5) drawChart(); });
    ro.observe(host);
    const prev = ui.teardown;
    ui.teardown = () => { ro.disconnect(); if (prev) prev(); };
    return c;
  }

  function setView(v, noDraw) {
    S.view = v;
    ui.seg.querySelectorAll('button').forEach((b, n) => b.setAttribute('aria-pressed', String((n === 0) === (v === 'all'))));
    if (!noDraw) { drawChart(); if (!S.playing) setText(ui.playBtn, S.i >= rangeFrames(S.rec)[1] ? 'Replay' : 'Play'); }
  }
  const viewRange = (rec) => (S.view === 'motion' ? rec.focus : [rec.t0, rec.t1]);

  function highlight(oid) {
    if (!ui.chart) return;
    ui.chart.svg.querySelectorAll('[data-oid]').forEach((n) => n.classList.toggle('dim', oid !== null && n.getAttribute('data-oid') !== oid));
  }

  function niceScale(min, max, want, bound) {
    let lo = min, hi = max;
    if (!(hi - lo > 0)) { const c = isFinite(lo) ? lo : 0; lo = c - 2.5; hi = c + 2.5; }
    if (hi - lo < 4) { const c = (hi + lo) / 2; lo = c - 2; hi = c + 2; }
    const pad = (hi - lo) * 0.09; lo -= pad; hi += pad;
    if (bound) {                       /* positions cannot leave the image: do not pad past its edges */
      if (min >= bound[0]) lo = Math.max(lo, bound[0]);
      if (max <= bound[1]) hi = Math.min(hi, bound[1]);
    }
    const raw = (hi - lo) / want, mag = Math.pow(10, Math.floor(Math.log10(raw))), norm = raw / mag;
    const step = (norm < 1.5 ? 1 : norm < 3.5 ? 2 : norm < 7.5 ? 5 : 10) * mag;
    const ticks = [];
    for (let v = Math.ceil(lo / step - 1e-9) * step; v <= hi + step * 1e-6; v += step) ticks.push(+v.toFixed(8));
    return { lo, hi, ticks, step };
  }
  function timeTicks(v0, v1, px) {
    const want = Math.max(2, Math.floor(px / (px < 360 ? 54 : 74)));
    const raw = (v1 - v0) / want;
    const step = [0.05, 0.1, 0.2, 0.25, 0.5, 1, 2].find((s) => s >= raw) || 2;
    const out = [];
    for (let t = Math.ceil(v0 / step - 1e-9) * step; t <= v1 + 1e-9; t += step) out.push(+t.toFixed(6));
    return { step, ticks: out };
  }

  function buildLanes(rec) {
    const lanes = [];
    const order = (id) => (rec.byId[id] ? rec.byId[id].k : 99);
    if (rec.inputs.length) lanes.push({ key: 'input', input: true, label: 'recorded input', color: INPUT_COLOR, items: rec.inputs.map((inp, n) => ({ n, t0: inp.t, t1: inp.t, label: inp.label })) });
    const by = new Map();
    rec.events.forEach((e, n) => {
      const key = e.rel ? e.ids[0] + '>' + e.rel : e.ids.join('+');
      let L = by.get(key);
      if (!L) {
        L = { key, input: false, rel: !!e.rel, order: order(e.ids[0]), label: e.rel ? e.ids[0] + ' vs ' + e.rel : e.ids.join(' + '),
          title: e.rel ? e.ids[0] + ' relative to ' + e.rel : e.ids.join(' and '), color: (rec.byId[e.ids[0]] || {}).color || '#94a3b8', items: [] };
        by.set(key, L); lanes.push(L);
      }
      L.items.push({ n, e, t0: e.t[0], t1: e.t[1], label: styleOf(e.ty).short });
    });
    lanes.sort((a, b) => (a.input ? -1 : b.input ? 1 : 0) || ((a.rel ? 1 : 0) - (b.rel ? 1 : 0)) || (a.order - b.order));
    return lanes;
  }

  function drawChart() {
    const rec = S.rec, hostEl = ui.chartHost;
    const W = Math.floor(hostEl.clientWidth);
    if (W < 220) return;
    ui.chartW = hostEl.clientWidth;
    const wide = W >= 760;
    const x0 = wide ? 124 : 42, x1 = W - (wide ? 18 : 10);
    const [v0, v1] = viewRange(rec);
    const tx = (t) => x0 + (t - v0) / (v1 - v0) * (x1 - x0);
    const inView = (t0, t1) => t1 >= v0 - 1e-9 && t0 <= v1 + 1e-9;
    const ROW = 18, CAP = wide ? 0 : 15, LPAD = 5, GAP = 4;
    const lanes = buildLanes(rec);

    let y = 4;
    for (const L of lanes) {
      const rowsRight = [];
      L.items = L.items.filter((it) => inView(it.t0, it.t1));
      L.items.sort((a, b) => (a.t0 + a.t1) - (b.t0 + b.t1) || a.n - b.n);
      for (const it of L.items) {
        it.xm = tx((it.t0 + it.t1) / 2);
        const w = measure(it.label, 11, 600);
        let left = it.xm - 9, right = it.xm + 12 + w;
        it.flip = false;
        if (right > x1 + 6) { it.flip = true; left = it.xm - 12 - w; right = it.xm + 9; }
        it.w = w;
        let r = 0;
        while (r < rowsRight.length && left < rowsRight[r] + 6) r++;
        rowsRight[r] = right; it.row = r;
      }
      L.rows = Math.max(1, rowsRight.length);
      L.y = y; L.h = CAP + LPAD * 2 + L.rows * ROW;
      y += L.h + GAP;
    }
    const lanesBottom = y;
    const CH = wide ? 138 : 112, REGION_GAP = 26, TH = wide ? 0 : 16;
    const regions = [{ key: 'x', top: lanesBottom + 10 + TH, h: CH }, { key: 'y', top: lanesBottom + 10 + TH + CH + REGION_GAP + TH, h: CH }];
    const axisY = regions[1].top + CH + 8;
    const H = axisY + 46;

    /* value scales from the samples inside the visible time range */
    for (const R of regions) {
      let lo = Infinity, hi = -Infinity;
      const idx = R.key === 'x' ? 0 : 1;
      for (const o of rec.objects) for (let i = 0; i < rec.n; i++) {
        const row = o.f[i];
        if (!rowOk(row) || rec.t[i] < v0 - 1e-9 || rec.t[i] > v1 + 1e-9) continue;
        const v = row[idx];
        if (v < lo) lo = v;
        if (v > hi) hi = v;
      }
      R.sc = niceScale(lo, hi, wide ? 4 : 3, [0, rec.size[idx]]);
      R.ty = R.key === 'x' ? (v) => R.top + (R.sc.hi - v) / (R.sc.hi - R.sc.lo) * R.h
                          : (v) => R.top + (v - R.sc.lo) / (R.sc.hi - R.sc.lo) * R.h;    /* y axis flipped: up is up in the image */
    }

    const svg = sv('svg', { class: 'ch', width: W, height: H, viewBox: '0 0 ' + W + ' ' + H, role: 'img',
      'aria-label': 'Tracks of ' + rec.objects.map((o) => o.id).join(', ') + ' over ' + (v1 - v0).toFixed(2) + ' seconds with ' + rec.events.length + ' events. The events table below lists every event.' });
    const defs = sv('defs');
    defs.append(sv('clipPath', { id: 'clip-plot' }, sv('rect', { x: x0, y: 0, width: x1 - x0, height: H })));
    const hatch = sv('pattern', { id: 'hatch', width: 6, height: 6, patternUnits: 'userSpaceOnUse', patternTransform: 'rotate(45)' }, sv('rect', { width: 6, height: 6, fill: 'rgba(143,155,189,.10)' }), sv('line', { x1: 0, y1: 0, x2: 0, y2: 6, stroke: 'rgba(143,155,189,.55)', 'stroke-width': 1.6 }));
    defs.append(hatch);
    rec.objects.forEach((o) => defs.append(sv('g', { id: 'sm-' + o.k }, seriesMark(o.k, o.color, 3.7))));
    svg.append(defs);

    /* time grid and axis */
    const tt = timeTicks(v0, v1, x1 - x0);
    const grid = sv('g', { class: 'grid' });
    for (const t of tt.ticks) grid.append(sv('line', { x1: tx(t), x2: tx(t), y1: 2, y2: axisY }));
    svg.append(grid);

    /* lanes */
    const gl = sv('g', { class: 'lanes' });
    ui.markers = [];
    for (const L of lanes) {
      gl.append(sv('rect', { class: 'lane', x: x0, y: L.y, width: x1 - x0, height: L.h, rx: 6 }));
      const lab = sv('text', { class: 'lane-l', x: wide ? 8 : x0 + 6, y: L.y + (wide ? L.h / 2 + 4 : 13), 'text-anchor': 'start' }, L.label);
      lab.append(sv('title', {}, L.title || L.label));
      if (wide) { lab.setAttribute('textLength', Math.min(measure(L.label, 11.5, 600), x0 - 16)); lab.setAttribute('lengthAdjust', 'spacingAndGlyphs'); }
      gl.append(lab);
      for (const it of L.items) {
        const cy = L.y + CAP + LPAD + it.row * ROW + ROW / 2;
        if (L.input) {
          const g = sv('g', { class: 'mk input', transform: 'translate(' + it.xm + ' ' + cy + ')' });
          g.append(sv('line', { class: 'mk-bar', x1: 0, x2: 0, y1: -ROW / 2 + 1, y2: ROW / 2 - 1, stroke: INPUT_COLOR, 'stroke-width': 2 }));
          g.append(sv('path', { d: 'M-5 -4L5 -4L0 4Z', fill: 'none', stroke: INPUT_COLOR, 'stroke-width': 1.6, 'stroke-linejoin': 'round' }));
          g.append(sv('text', { class: 'mk-l', x: it.flip ? -12 : 12, y: 4, 'text-anchor': it.flip ? 'end' : 'start', fill: INPUT_COLOR }, it.label));
          g.append(sv('title', {}, 'Recorded input: ' + it.label + ' at ' + secs(it.t0) + ' (from the capture harness, not measured from pixels)'));
          gl.append(g);
          continue;
        }
        const st = styleOf(it.e.ty);
        const g = sv('g', { class: 'mk', 'data-ev': it.n, transform: 'translate(' + it.xm + ' ' + cy + ')' });
        const bw = Math.max(2, tx(it.t1) - tx(it.t0));
        g.append(sv('rect', { class: 'mk-bar', x: tx(it.t0) - it.xm, y: -ROW / 2 + 1, width: bw, height: ROW - 2, rx: 1, fill: st.color }));
        g.append(glyph(st.shape, st.color, 5));
        g.append(sv('text', { class: 'mk-l', x: it.flip ? -12 : 12, y: 4, 'text-anchor': it.flip ? 'end' : 'start', fill: st.color }, it.label));
        g.append(sv('rect', { class: 'mk-hit', x: it.flip ? -(it.w + 16) : -10, y: -ROW / 2, width: it.w + 26, height: ROW, fill: 'transparent' }));
        g.addEventListener('pointerenter', (ev) => hoverEvent(it.n, ev));
        g.addEventListener('pointermove', (ev) => moveTip(ev));
        g.addEventListener('pointerleave', () => hoverEvent(-1));
        g.addEventListener('click', (ev) => { ev.stopPropagation(); seekEvent(it.n); });
        gl.append(g);
        ui.markers[it.n] = g;
      }
    }
    svg.append(gl);

    /* x and y charts */
    const series = sv('g', { class: 'series' });
    const hatchBands = [];
    for (const R of regions) {
      series.append(sv('rect', { class: 'region', x: x0, y: R.top, width: x1 - x0, height: R.h, rx: 4 }));
      for (const tk of R.sc.ticks) {
        const yy = R.ty(tk);
        if (yy < R.top - 0.5 || yy > R.top + R.h + 0.5) continue;
        series.append(sv('line', { class: 'hgrid', x1: x0, x2: x1, y1: yy, y2: yy }));
        series.append(sv('text', { class: 'tick', x: x0 - 7, y: yy + 3.5, 'text-anchor': 'end' }, (R.sc.step < 1 ? tk.toFixed(1) : String(Math.round(tk)))));
      }
      const title = R.key === 'x' ? ['x (px)', 'left to right'] : ['y (px)', 'up = smaller y'];
      if (wide) {
        series.append(sv('text', { class: 'ax-title', x: 8, y: R.top + 15 }, title[0]));
        series.append(sv('text', { class: 'ax-sub', x: 8, y: R.top + 29 }, title[1]));
      } else series.append(sv('text', { class: 'ax-title', x: x0, y: R.top - 5 }, R.key === 'x' ? 'x (px), left to right' : 'y (px), up = smaller y'));
      const clip = sv('g', { 'clip-path': 'url(#clip-plot)' });
      /* frames without a measurement: a hatched band, never a line */
      rec.objects.forEach((o) => {
        let a = -1;
        for (let i = 0; i <= rec.n; i++) {
          const bad = i < rec.n && !rowOk(o.f[i]);
          if (bad && a < 0) a = i;
          if (!bad && a >= 0) {
            const b = i - 1;
            const xa = Math.max(x0, tx(rec.t[a])), xb = Math.min(x1, tx(rec.t[b]));
            if (inView(rec.t[a], rec.t[b]) && xb >= xa) {
              clip.append(sv('rect', { class: 'nobs', 'data-oid': o.id, x: xa, y: R.top, width: Math.max(2, xb - xa), height: R.h, fill: 'url(#hatch)' }));
              if (R.key === 'x' && xb - xa > 96) hatchBands.push({ x: xa, y: R.top + R.h - 6, text: o.id + ': no measurement', color: o.color, w: xb - xa });
            }
            a = -1;
          }
        }
      });
      const idx = R.key === 'x' ? 0 : 1;
      const perFrame = (x1 - x0) / ((v1 - v0) / (((rec.clock.median_ms) || 16.7) / 1000));    /* pixels per frame */
      const stride = Math.max(1, Math.round(38 / Math.max(perFrame, 0.2)));                    /* a marker about every 38 px */
      const rim = rec.objects.map((a, ka) => {
        let depth = 0;
        for (let kb = ka + 1; kb < rec.objects.length; kb++) {
          let both = 0, same = 0;
          for (let i = 0; i < rec.n; i++) {
            const ra = a.f[i], rb = rec.objects[kb].f[i];
            if (!rowOk(ra) || !rowOk(rb) || rec.t[i] < v0 || rec.t[i] > v1) continue;
            both++;
            if (Math.abs(R.ty(ra[idx]) - R.ty(rb[idx])) < 1.8) same++;
          }
          if (both && same / both >= 0.25) depth++;
        }
        return Math.min(depth, 2);
      });
      rec.objects.forEach((o, k) => {
        let d = '', pen = false;
        const marks = [];
        const phase = Math.round(stride * k / rec.objects.length);
        for (let i = 0; i < rec.n; i++) {
          const row = o.f[i];
          if (!rowOk(row) || rec.t[i] < v0 - 0.05 * (v1 - v0) || rec.t[i] > v1 + 0.05 * (v1 - v0)) { pen = false; continue; }
          const px = tx(rec.t[i]), py = R.ty(row[idx]);
          d += (pen ? 'L' : 'M') + px.toFixed(1) + ' ' + py.toFixed(1);
          pen = true;
          if ((i + phase) % stride === 0) marks.push([px, py]);
        }
        const g = sv('g', { class: 'ser', 'data-oid': o.id });
        g.append(sv('path', { d, fill: 'none', stroke: o.color, 'stroke-width': 2.2 + 1.9 * rim[k], 'stroke-linejoin': 'round', 'stroke-linecap': 'round' }));
        for (const [px, py] of marks) g.append(sv('use', { href: '#sm-' + k, x: px.toFixed(1), y: py.toFixed(1) }));
        clip.append(g);
      });
      series.append(clip);
      for (const hb of hatchBands.splice(0)) series.append(sv('text', { class: 'nobs-l', x: hb.x + 6, y: hb.y, fill: hb.color }, hb.text));
    }
    svg.append(series);

    /* time axis */
    const ax = sv('g', { class: 'axis' });
    ax.append(sv('line', { x1: x0, x2: x1, y1: axisY, y2: axisY }));
    for (const t of tt.ticks) {
      ax.append(sv('line', { x1: tx(t), x2: tx(t), y1: axisY, y2: axisY + 4 }));
      ax.append(sv('text', { class: 'tick', x: tx(t), y: axisY + 17, 'text-anchor': 'middle' }, tt.step < 0.1 ? t.toFixed(2) : tt.step < 1 ? t.toFixed(2).replace(/0$/, '') : t.toFixed(1)));
    }
    /* the events also sit on the time axis itself: a short tick in the event's colour at the middle of its interval */
    for (const e of rec.events) {
      if (!inView(e.t[0], e.t[1])) continue;
      const ex = tx((e.t[0] + e.t[1]) / 2);
      ax.append(sv('line', { class: 'ev-tick', x1: ex, x2: ex, y1: axisY - 7, y2: axisY, stroke: styleOf(e.ty).color, 'stroke-width': 2.2, 'stroke-linecap': 'round' }));
    }
    ax.append(sv('text', { class: 'ax-title', x: wide ? 8 : 2, y: axisY + 17, 'text-anchor': 'start' }, wide ? 'time (s)' : 't (s)'));
    svg.append(ax);

    /* guides for the events that just happened or are hovered */
    ui.guides = sv('g', { class: 'guides', 'clip-path': 'url(#clip-plot)' });
    svg.append(ui.guides);

    /* playhead, sample dots, time label */
    const cur = sv('g', { class: 'cursor' });
    const line = sv('line', { class: 'ph', y1: 2, y2: axisY });
    const label = sv('g', { class: 'ph-lab' }, sv('rect', { x: -30, y: 0, width: 60, height: 17, rx: 5 }), sv('text', { x: 0, y: 12.5, 'text-anchor': 'middle' }, ''));
    label.setAttribute('transform', 'translate(0 ' + (axisY + 24) + ')');
    cur.append(line);
    const dotEls = [];
    regions.forEach((R) => rec.objects.forEach((o, k) => {
      const c = sv('circle', { class: 'ph-dot', 'data-oid': o.id, r: Math.max(3, 5.2 - k * 0.7), fill: o.color });
      cur.append(c);
      dotEls.push({ el: c, R, o, idx: R.key === 'x' ? 0 : 1 });
    }));
    cur.append(label);
    svg.append(cur);

    /* pointer layer: click or drag to move through the clip */
    const hit = sv('rect', { class: 'hit', x: x0, y: 0, width: x1 - x0, height: axisY });
    svg.insertBefore(hit, gl);
    const seekX = (ev) => {
      const r = svg.getBoundingClientRect();
      const t = v0 + clamp((ev.clientX - r.left - x0) / (x1 - x0), 0, 1) * (v1 - v0);
      pause(); setFrame(nearestFrame(rec, t), true);
    };
    let dragging = false;
    hit.addEventListener('pointerdown', (ev) => { dragging = true; hit.setPointerCapture(ev.pointerId); seekX(ev); });
    hit.addEventListener('pointermove', (ev) => { if (dragging) seekX(ev); });
    const stop = (ev) => { dragging = false; try { hit.releasePointerCapture(ev.pointerId); } catch (e) { /* not captured */ } };
    hit.addEventListener('pointerup', stop); hit.addEventListener('pointercancel', stop);

    hostEl.replaceChildren(svg);
    ui.chart = { svg, tx, v0, v1, x0, x1, axisY, line, label, dotEls, regions, lanes, inView };
    ui.curKey = '';
    updateCursor();
    updateGuides(true);
  }

  function updateCursor() {
    const c = ui.chart, rec = S.rec;
    if (!c) return;
    const i = S.i, t = rec.t[i];
    const inside = t >= c.v0 - 1e-9 && t <= c.v1 + 1e-9;
    const x = c.tx(t);
    c.line.style.display = c.label.style.display = inside ? '' : 'none';
    if (inside) {
      c.line.setAttribute('x1', x); c.line.setAttribute('x2', x);
      const lx = clamp(x, c.x0 + 30, c.x1 - 30);
      c.label.setAttribute('transform', 'translate(' + lx + ' ' + (c.axisY + 24) + ')');
      setText(c.label.querySelector('text'), t.toFixed(3) + ' s');
    }
    for (const d of c.dotEls) {
      const row = d.o.f[i];
      if (inside && rowOk(row)) { d.el.style.display = ''; d.el.setAttribute('cx', x); d.el.setAttribute('cy', d.R.ty(row[d.idx])); }
      else d.el.style.display = 'none';
    }
  }

  /* Guides and highlights for events that just happened (or are hovered). */
  function updateGuides(force) {
    const c = ui.chart, rec = S.rec;
    if (!c) return;
    const now = currentEvents(rec, S.i);
    const key = now.join(',') + '|' + S.hover;
    if (!force && key === ui.curKey) return;
    ui.curKey = key;
    const mark = new Set(now);
    if (S.hover >= 0) mark.add(S.hover);
    ui.markers.forEach((g, n) => { if (g) { g.classList.toggle('cur', mark.has(n)); g.classList.toggle('hov', n === S.hover); } });
    ui.guides.replaceChildren();
    for (const n of mark) {
      const e = rec.events[n];
      if (!c.inView(e.t[0], e.t[1])) continue;
      const st = styleOf(e.ty), xa = c.tx(e.t[0]), xb = c.tx(e.t[1]);
      const x = (xa + xb) / 2;
      ui.guides.append(sv('rect', { x: xa, y: 2, width: Math.max(2, xb - xa), height: c.axisY - 2, fill: st.color, opacity: n === S.hover ? 0.28 : 0.16 }));
      ui.guides.append(sv('line', { x1: x, x2: x, y1: 2, y2: c.axisY, stroke: st.color, 'stroke-width': 1, 'stroke-dasharray': '3 3', opacity: 0.9 }));
    }
    /* table rows and the readout list */
    if (ui.rows) ui.rows.forEach((tr, n) => tr.classList.toggle('cur', mark.has(n)));
    ui.nowList.replaceChildren(...(now.length ? now.map((n) => {
      const e = rec.events[n];
      return el('li', {}, glyphIcon(e.ty), el('button', { type: 'button', class: 'link', text: e.ty, onclick: () => seekEvent(n) }), ' ' + objText(e));
    }) : [el('li', { class: 'none', text: 'none' })]));
  }

  const objText = (e) => (e.rel ? e.ids[0] + ' relative to ' + e.rel : e.ids.join(' and '));

  /* ------------------------------------------------------------------ events: hover, seek, table */
  function hoverEvent(n, ev) {
    S.hover = n;
    updateGuides();
    if (n < 0) { hideTip(); return; }
    const e = S.rec.events[n];
    tip.replaceChildren(el('b', { text: e.ty }), ' ' + objText(e),
      el('span', { text: secs(e.t[0]) + ' ' + ENDASH + ' ' + secs(e.t[1]) + ' (frames ' + e.f[0] + ENDASH + e.f[1] + (e.ok ? '' : ', timing unresolved') + ')' }),
      el('span', { text: e.d }));
    tip.hidden = false;
    if (ev) moveTip(ev);
  }
  function moveTip(ev) {
    const pad = 14, w = tip.offsetWidth, h = tip.offsetHeight;
    let x = ev.clientX + pad, y = ev.clientY + pad;
    if (x + w > window.innerWidth - 6) x = ev.clientX - w - pad;
    if (y + h > window.innerHeight - 6) y = ev.clientY - h - pad;
    tip.style.left = Math.max(6, x) + 'px'; tip.style.top = Math.max(6, y) + 'px';
  }
  function hideTip() { tip.hidden = true; }

  function seekEvent(n) {
    const e = S.rec.events[n];
    pause();
    S.hover = -1;
    setFrame(e.f[1], true);
    const calm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    ui.screen.scrollIntoView({ block: 'nearest', behavior: calm ? 'auto' : 'smooth' });
  }

  function buildEvents(rec) {
    const rows = rec.events.map((e, n) => {
      const st = styleOf(e.ty);
      const tr = el('tr', { 'data-ev': n },
        el('td', { class: 'c-n num', text: String(n + 1) }),
        el('td', { class: 'c-ty' }, el('button', { type: 'button', class: 'evbtn', title: 'Show the frame where this event is first visible (frame ' + e.f[1] + ')', onclick: () => seekEvent(n) }, glyphIcon(e.ty), el('span', { text: e.ty }))),
        el('td', { class: 'c-obj', text: objText(e) }),
        el('td', { class: 'c-int num', text: e.t[0].toFixed(3) + ENDASH + e.t[1].toFixed(3) }),
        el('td', { class: 'c-fr num', text: e.f[0] + ENDASH + e.f[1] }),
        el('td', { class: 'c-d', text: e.d + (e.ok ? '' : ' (timing unresolved)') }));
      tr.addEventListener('pointerenter', () => { S.hover = n; updateGuides(); });
      tr.addEventListener('pointerleave', () => { S.hover = -1; updateGuides(); });
      return tr;
    });
    ui.rows = rows;
    const table = el('table', { class: 'evtable' },
      el('caption', { class: 'sr-only', text: 'Events measured in this recording' }),
      el('thead', {}, el('tr', {}, ['#', 'Event', 'Object', 'Time interval (s)', 'Frames', 'What was measured'].map((h, k) => el('th', { scope: 'col', class: ['c-n', 'c-ty', 'c-obj', 'c-int', 'c-fr', 'c-d'][k], text: h })))),
      el('tbody', {}, rows));
    const wrap = el('div', { class: 'twrap', tabindex: '0', role: 'region', 'aria-label': 'Events table, scrollable' }, rec.events.length ? table : el('p', { class: 'none pad', text: 'No events were measured in this recording.' }));
    const kinds = [...new Set(rec.events.map((e) => e.ty))];
    return el('section', { class: 'card events', 'aria-labelledby': 'ev-title' },
      el('div', { class: 'tl-head' }, el('h2', { id: 'ev-title', text: 'Events' }),
        el('p', { class: 'tl-sub', text: rec.events.length + ' events: ' + kinds.map((k) => rec.events.filter((e) => e.ty === k).length + ' ' + k).join(', ') })),
      el('p', { class: 'cs', text: 'Each event is located between two real frames, so its time is an interval, not an instant: nothing inside the interval is interpolated or claimed. Pick an event to jump to the frame where it is first visible.' }),
      wrap);
  }

  /* ------------------------------------------------------------------ AWS receipt (game tab) */
  const FIELD_NOTE = {
    opencv_runtime: 'the engine build record: version, modules, build flags',
    phase_shifts_px: 'a phase-correlation camera diagnostic whose last digits differ between x86 and Arm',
  };
  function buildReceipt(rec) {
    const r = rec.receipt;
    if (!r) return null;
    const lib = (name) => name.replace(/^libopencv_/, '').replace(/\.so.*$/, '');
    const local = r.local || {};
    const ob = r.objects[0];
    const date = new Date(r.checked + 'T00:00:00Z');
    const nice = isNaN(date) ? r.checked : date.getUTCDate() + ' ' + ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'][date.getUTCMonth()] + ' ' + date.getUTCFullYear();
    const mine = rec.objects[0];
    const row = (label, a, b, cls) => el('tr', { class: cls || '' }, el('th', { scope: 'row', text: label }), el('td', {}, a), el('td', {}, b));
    const table = el('table', { class: 'cmp' },
      el('caption', { class: 'sr-only', text: 'The AWS COOL worker compared with the local measurement shown on this page' }),
      el('thead', {}, el('tr', {}, el('th', { scope: 'col' }, el('span', { class: 'sr-only', text: 'Field' })), el('th', { scope: 'col', text: 'AWS COOL worker' }), el('th', { scope: 'col', text: 'Local run' }))),
      el('tbody', {},
        row('OpenCV', r.engine.opencv + (r.engine.cool_build ? ' (COOL build)' : ''), (D.opencv_local || local.opencv) + ' (the measurement on this page)'),
        row('Platform', r.engine.system + ' ' + r.engine.architecture, D.local_platform || ''),
        row('Time', r.worker_seconds.toFixed(2) + ' s worker wall time', local.seconds != null ? local.seconds.toFixed(2) + ' s in the same check' : ''),
        row('Origin', r.origin + ' (computed for this request, not reused)', 'computed locally'),
        row('Measurement', r.measurement_status, rec.status),
        row('Objects', ob.id + ': ' + (ob.valid_ratio * 100).toFixed(0) + '% valid, ' + ob.frames + ' frames', mine.id + ': ' + (mine.valid_ratio * 100).toFixed(0) + '% valid, ' + rec.n + ' frames'),
        row('Events', String(r.events), String(rec.events.length))));
    const verdict = el('div', { class: 'verdict' },
      el('h3', { text: 'Local equivalence' }),
      el('p', {}, el('b', { class: local.equivalent_excluding ? 'ok' : 'bad', text: local.equivalent_excluding ? 'Equivalent once two fields that feed no decision are excluded. ' : 'Not equivalent. ' }),
        'Every tracked position, validity flag and event was compared with the local measurement under the service’s equivalence policy (exact for identities, validity and events; a small numeric tolerance for positions).'),
      el('p', {}, 'The strict policy as written reported ' + local.strict_differences + ' differences, all in ' + (local.difference_fields || []).length + ' fields: ',
        (local.difference_fields || []).map((f, k) => [k ? '; ' : '', el('code', { text: f }), ' (' + (FIELD_NOTE[f] || 'a report-only field') + ')']),
        '. With those fields excluded, ' + local.remaining_differences + ' differences remain.'));
    return el('section', { class: 'card receipt', 'aria-labelledby': 'rc-title' },
      el('div', { class: 'tl-head' }, el('h2', { id: 'rc-title', text: 'Same recording on the AWS COOL worker' }), el('p', { class: 'tl-sub', text: 'receipt of a live run on ' + nice })),
      el('p', { class: 'cs', text: 'The same frames, selection and contract were measured by the live KiroClops service: an AWS Graviton4 worker that boots from the Cloud Optimized OpenCV (COOL) image. Fields below come from the worker’s delivery receipt; job and endpoint identifiers are left out. The worker time runs from claiming the job to the finished measurement, so it includes the download, the integrity check and the sandbox start; end to end (upload, queue, result) the request took ' + r.end_to_end_seconds.toFixed(1) + ' s. This is a receipt, not a benchmark.' }),
      el('div', { class: 'rc-grid' }, table, verdict),
      el('div', { class: 'libs' },
        el('h3', { text: 'COOL build identification: ' + r.engine.libraries.length + ' shared libraries mapped by the worker' }),
        el('p', { class: 'chips' }, r.engine.libraries.map((n) => el('code', { title: n, text: lib(n) }))),
        el('p', { class: 'cs', text: 'Each is libopencv_<module>.so.' + (r.engine.opencv.split('-')[0]) + '.' })));
  }

  /* ------------------------------------------------------------------ guide */
  function buildGuide(rec) {
    return el('section', { class: 'card guide', 'aria-labelledby': 'g-title' },
      el('h2', { id: 'g-title', text: 'How to read this page' }),
      el('div', { class: 'g-cols' },
        el('div', {}, el('h3', { text: 'What is drawn' }),
          el('ul', {},
            el('li', {}, el('b', { text: 'Box and ring. ' }), 'The box is the visible geometry OpenCV measured (for an object tracked by template alone, the size of its template); the ring is the measured anchor point, the same x and y that the charts plot.'),
            el('li', {}, el('b', { text: 'No position without a measurement. ' }), 'If a frame has no valid measurement for an object, nothing is drawn for it and the readout says why. Nothing is interpolated or predicted.'),
            el('li', {}, el('b', { text: 'Events are intervals. ' }), 'An event is located between two real frames. The bar on its marker spans that interval; the measurement does not claim a moment inside it.'),
            rec.connections.length ? el('li', {}, el('b', { text: 'Connectors. ' }), 'The green segments are the visible connector lines as measured, with their end points; they are measured, never snapped to the boxes.') : null)),
        el('div', {}, el('h3', { text: 'About this recording' }),
          el('dl', { class: 'facts' }, rec.facts.map(([k, v]) => [el('dt', { text: k }), el('dd', { text: v })]))),
        el('div', {}, el('h3', { text: 'How the numbers are produced' }),
          el('ul', {},
            el('li', {}, 'Each object is located with ', el('code', { text: 'cv2.matchTemplate' }), ' (', el('code', { text: 'TM_CCOEFF_NORMED' }), ') around its previous position. A match counts only above a score limit and with a margin over the next-best peak; where a visible outline was selected, ', el('code', { text: 'cv2.findContours' }), ' gives the box.'),
            rec.connections.length ? el('li', {}, 'Connector end points come from ', el('code', { text: 'cv2.Canny' }), ' edges and a line fit on the visible line.') : null,
            el('li', {}, 'A background patch checks that the camera did not move; ', el('code', { text: 'cv2.phaseCorrelate' }), ' adds a sub-pixel shift report that gates nothing.'),
            el('li', {}, 'Events come from a fixed rule set on the valid tracks (' + rec.policy + '): rest band ' + rec.options.rest_radius_px + ' px, rest for at least ' + rec.options.rest_duration_s + ' s, event time resolved to ' + rec.options.max_event_uncertainty_s + ' s or better.'),
            el('li', {}, 'Frames are lossless copies of the recorded PNG frames. Every number comes from measuring them with the code path the AWS worker runs; ', el('a', { href: 'data.js', text: 'data.js' }), ' holds the numbers and ', el('a', { href: 'build_data.py', text: 'build_data.py' }), ' regenerates them.')))));
  }

  /* ------------------------------------------------------------------ paint everything for the current frame */
  function paint() {
    if (!ui || !S.rec) return;
    ui.lastKey = S.rec.id + ':' + S.i;
    paintFrame();
    updateReadout();
    if (+ui.scrub.value !== S.i) ui.scrub.value = S.i;
    ui.scrub.setAttribute('aria-valuetext', 'frame ' + S.i + ', ' + secs(S.rec.t[S.i]));
    updateCursor();
    updateGuides();
  }
  function layoutAll() {
    sizeCanvas();
    drawChart();
  }

  window.addEventListener('keydown', (ev) => { if (ev.key === 'Escape') { pause(); } });

  /* ------------------------------------------------------------------ boot */
  const wanted = (location.hash || '').replace('#', '');
  const first = Math.max(0, recs.findIndex((r) => r.id === wanted));
  selectTab(first);
  window.addEventListener('hashchange', () => {
    const k = recs.findIndex((r) => r.id === (location.hash || '').replace('#', ''));
    if (k >= 0 && recs[k] !== S.rec) selectTab(k);
  });
  window.kcExplorer = { state: S, select: selectTab, setFrame, play, pause };   /* handle for tests and for deep links */
})();
